(() => {
'use strict';
const $=id=>document.getElementById(id),W=10,H=8,KEY='beyond-rebuilt-1',DIRS=[[0,-1],[1,0],[0,1],[-1,0]],atlas=new Image(),sprites=new Map();
const floor=$('terrain'),ctx=floor.getContext('2d'),cells=[],pieces=new Map();let selected=null,path=[],busy=false,diceTimer;
function random(n){const a=new Uint32Array(1),limit=4294967296-4294967296%n;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%n+1}
function fresh(){return{round:1,combat:true,active:'eldar',gold:0,xp:0,level:1,potions:2,chest:false,relic:false,complete:false,seed:random(99999),party:[{id:'eldar',name:'Эльдар',genitive:'Эльдара',kind:0,x:5,y:4,hp:24,max:24,facing:2,move:4,acted:false,range:1,attack:4,damage:8},{id:'mira',name:'Мира',genitive:'Миры',kind:1,x:3,y:6,hp:18,max:18,facing:2,move:4,acted:false,range:5,attack:4,damage:6},{id:'bor',name:'Бор',genitive:'Бора',kind:2,x:6,y:6,hp:28,max:28,facing:2,move:3,acted:false,range:1,attack:3,damage:8}],enemies:[{id:'e1',name:'Скелетный страж',kind:3,x:6,y:3,hp:13,max:13,facing:0},{id:'e2',name:'Костяной дозорный',kind:3,x:7,y:3,hp:13,max:13,facing:0}],logs:['Страж поднимает меч. Победите стражей и найдите реликвию исчезнувшего колокола.']}}
let state;try{state=JSON.parse(localStorage.getItem(KEY))||fresh()}catch{state=fresh()}
const props=[{id:'keeper',x:5,y:1,kind:20,name:'Эллен · хранительница'},{id:'chest',x:2,y:2,kind:17,name:'Сундук'},{id:'altar',x:7,y:1,kind:18,name:'Алтарь'},{id:'pillar1',x:3,y:2,kind:19,name:'Каменная колонна'},{id:'pillar2',x:7,y:5,kind:19,name:'Каменная колонна'}];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}
function tell(s){state.logs.push(s);save()}
function active(){return state.party.find(p=>p.id===state.active)}
function all(){return [...state.party,...state.enemies].filter(p=>p.hp>0)}
function dist(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}
function same(a,b){return a.x===b.x&&a.y===b.y}
function entity(p){return all().find(e=>same(e,p))}
function prop(p){return props.find(e=>same(e,p)&&!(e.id==='chest'&&state.chest)&&!(e.id==='keeper'&&state.combat))}
function blocked(p){return p.x<=0||p.x>=W-1||p.y<=0||p.y>=H-1||!!prop(p)||((p.x===2||p.x===8)&&(p.y===5||p.y===6))}
function pathTo(a,b){if(blocked(b)||entity(b))return null;const q=[[{x:a.x,y:a.y}]],seen=new Set([a.x+','+a.y]);while(q.length){const path=q.shift(),last=path.at(-1);if(same(last,b))return path.slice(1);for(const [dx,dy] of DIRS){const n={x:last.x+dx,y:last.y+dy},k=n.x+','+n.y;if(seen.has(k)||blocked(n)||entity(n))continue;seen.add(k);q.push([...path,n])}}return null}
function line(a,b){if(same(a,b)||a.x!==b.x&&a.y!==b.y)return false;const dx=Math.sign(b.x-a.x),dy=Math.sign(b.y-a.y);let p={x:a.x+dx,y:a.y+dy};while(!same(p,b)){if(blocked(p)||entity(p))return false;p={x:p.x+dx,y:p.y+dy}}return true}
function canAttack(a,b){return !a.acted&&b.hp>0&&dist(a,b)<=a.range&&line(a,b)}
function face(a,b){if(b.x>a.x)a.facing=1;else if(b.x<a.x)a.facing=3;else if(b.y<a.y)a.facing=2;else a.facing=0}
function roll(n=20,show=true){const result=random(n);if(show){$('number').textContent=result;$('dice').hidden=false;clearTimeout(diceTimer);diceTimer=setTimeout(()=>$('dice').hidden=true,1700)}return result}
function cutAtlas(){const c=document.createElement('canvas');c.width=atlas.width;c.height=atlas.height;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(atlas,0,0);const sw=atlas.width/4,rows=[0,.2153,.4115,.6061,.7974,1],anchors=[.1754,.3748,.575,.7663];for(let i=0;i<20;i++){const row=Math.floor(i/4),col=i%4,sx=Math.round(col*sw),sy=Math.round(rows[row]*atlas.height),w=Math.floor(sw),h=Math.round((rows[row+1]-rows[row])*atlas.height),data=x.getImageData(sx,sy,w,h).data;let l=w,t=h,r=0,b=0;for(let yy=0;yy<h;yy++)for(let xx=0;xx<w;xx++)if(data[(yy*w+xx)*4+3]>40){l=Math.min(l,xx);t=Math.min(t,yy);r=Math.max(r,xx);b=Math.max(b,yy)}const s={sx:sx+l,sy:sy+t,w:r-l+1,h:b-t+1};s.ax=s.w/2;s.ay=row<4?anchors[row]*atlas.height-s.sy:s.h/2;if(row<4){const baseRow=Math.round(anchors[row]*atlas.height-sy);let left=w,right=-1;for(let yy=Math.max(0,baseRow-3);yy<Math.min(h,baseRow+4);yy++)for(let xx=0;xx<w;xx++){const k=(yy*w+xx)*4;if(data[k+3]>100&&data[k]>data[k+1]*1.12&&data[k+1]>data[k+2]*1.05){left=Math.min(left,xx);right=Math.max(right,xx)}}if(right>left)s.ax=(left+right)/2-l}sprites.set(i,s)}render()}
function sprite(canvas,i,mode='portrait'){if(i===20&&window.drawKeeper){window.drawKeeper(canvas,mode);return}const s=sprites.get(i);canvas.width=256;canvas.height=320;const c=canvas.getContext('2d');c.clearRect(0,0,256,320);if(!s)return;const scale=mode==='figure'?Math.min(184/s.w,270/s.h):mode==='prop'?Math.min(215/s.w,268/s.h):Math.min(238/s.w,286/s.h);const w=s.w*scale,h=s.h*scale;if(mode==='figure')c.drawImage(atlas,s.sx,s.sy,s.w,s.h,128-s.ax*scale,320/1.45-s.ay*scale,w,h);else c.drawImage(atlas,s.sx,s.sy,s.w,s.h,128-w/2,160-h/2,w,h)}
function art(i,mode='portrait'){const c=document.createElement('canvas');c.className='sprite';sprite(c,i,mode);return c}
function terrain(){
 const size=$('board').clientWidth,dpr=Math.min(devicePixelRatio||1,2);floor.width=Math.round(size*dpr);floor.height=Math.round(size*H/W*dpr);const unit=floor.width/W;
 ctx.setTransform(unit,0,0,unit,0,0);ctx.imageSmoothingEnabled=true;ctx.fillStyle='#827861';ctx.fillRect(0,0,W,H);
 const s=sprites.get(16);
 for(let y=0;y<H;y++)for(let x=0;x<W;x++){
  ctx.save();ctx.translate(x+.5,y+.5);
  if(!window.drawTerrainTile||!window.drawTerrainTile(ctx,x,y,state.seed)){if(s)ctx.drawImage(atlas,s.sx,s.sy,s.w,s.h,-.5,-.5,1,1)}ctx.restore();
 }
 // The grid belongs to the floor, so every stone shares the same light direction.
 ctx.strokeStyle='#514b3c65';ctx.lineWidth=.018;ctx.beginPath();
 for(let x=1;x<W;x++){ctx.moveTo(x,1);ctx.lineTo(x,H-1)}for(let y=1;y<H;y++){ctx.moveTo(1,y);ctx.lineTo(W-1,y)}ctx.stroke();
 const ambient=ctx.createRadialGradient(5,3.5,1,5,3.5,5.6);ambient.addColorStop(0,'#22271900');ambient.addColorStop(.65,'#22271908');ambient.addColorStop(1,'#18241e4a');ctx.fillStyle=ambient;ctx.fillRect(0,0,W,H);
 ctx.fillStyle='#793e36';ctx.fillRect(4.25,6,1.5,1);ctx.strokeStyle='#bc965b';ctx.lineWidth=.025;ctx.strokeRect(4.35,6.04,1.3,.92);
 if(window.renderDecor)window.renderDecor(ctx);
 // Wide, quiet candle pools instead of a separate hard shadow on each tile.
 for(const [x,y,r]of[[1.2,3.5,1.7],[8.8,4.7,1.7],[7.5,1.5,1.8]]){const glow=ctx.createRadialGradient(x,y,0,x,y,r);glow.addColorStop(0,'#f4c47918');glow.addColorStop(.4,'#edba7010');glow.addColorStop(1,'#edba7000');ctx.fillStyle=glow;ctx.fillRect(x-r,y-r,r*2,r*2)}
}
function createCells(){for(let y=0;y<H;y++)for(let x=0;x<W;x++){const b=document.createElement('button');b.className='cell';b.setAttribute('role','gridcell');b.dataset.x=x;b.dataset.y=y;b.onclick=()=>select({x,y});$('cells').append(b);cells.push(b)}}
function select(p){if(busy)return;selected=p;path=[];const e=entity(p);if(e&&e.kind!==3){state.active=e.id;save()}else if(!e&&!blocked(p))path=pathTo(active(),p)||[];render()}
function renderPieces(){for(const e of all()){let el=pieces.get(e.id);if(!el){el=document.createElement('div');el.dataset.id=e.id;el.append(art(e.kind*4+e.facing,'figure'));$('pieces').append(el);pieces.set(e.id,el)}el.style.setProperty('--x',e.x);el.style.setProperty('--y',e.y);el.className='piece '+(e.kind===3?'enemy':'ally')+(e.id===state.active?' active':'')+(selected&&same(e,selected)?' targeted':'');sprite(el.firstChild,e.kind*4+e.facing,'figure')}for(const [id,el]of pieces)if(!all().some(e=>e.id===id)){el.remove();pieces.delete(id)}}
function renderObjects(){$('objects').replaceChildren();for(const p of props){if(p.id==='chest'&&state.chest||p.id==='keeper'&&state.combat)continue;const el=document.createElement('div');el.className='prop';el.dataset.id=p.id;el.style.setProperty('--x',p.x);el.style.setProperty('--y',p.y);el.append(art(p.kind,'prop'));$('objects').append(el)}}
function renderTarget(){const chosen=selected&&entity(selected),p=selected&&prop(selected),target=chosen||(!p&&state.enemies.find(e=>e.hp>0))||active();$('target-art').replaceChildren(art(p?p.kind:target.kind*4+(target.kind===3?0:target.facing),p?'prop':'portrait'));$('target-name').textContent=p?p.name:target.name;$('target-hp').textContent=p?(p.id==='chest'?'Монеты и зелье':p.id==='altar'?'Реликвия колокола':p.id==='keeper'?'Хранительница часовни':'Укрытие'):target.hp+' / '+target.max+' HP';$('target-bar').style.width=p?'0%':target.hp/target.max*100+'%';$('stats').innerHTML=p?'<p><span>◇</span><span>Взаимодействие вплотную</span></p>':'<p><span>⚔</span><span>Атака: '+(target.kind===3?4:target.attack)+'</span></p><p><span>♜</span><span>Защита: 2</span></p><p><span>▰</span><span>Передвижение: '+(target.kind===3||target.kind===2?3:4)+'</span></p>'}
function primary(){const a=active(),e=selected&&entity(selected),p=selected&&prop(selected);if(a.hp<=0)return{label:'Без сознания',enabled:false};if(p&&p.id==='keeper')return{label:'Говорить',enabled:!state.combat&&dist(a,p)===1,fn:()=>window.openKeeperDialogue?.()};if(p&&p.id==='altar'&&state.relic)return{label:'Реликвия найдена',enabled:false};if(e&&e.kind===3)return{label:'Атака',enabled:state.combat&&canAttack(a,e),fn:()=>attack(e)};if(p&&['chest','altar'].includes(p.id))return{label:p.id==='chest'?'Открыть':'Реликвия',enabled:!state.combat&&dist(a,p)===1,fn:()=>interact(p)};if(path.length)return{label:'Идти · '+path.length,enabled:!state.combat||path.length<=a.move,fn:move};return{label:'Атака',enabled:false}}
function render(){const a=active();$('title').textContent=state.complete?'Глава завершена':state.combat?'Бой · раунд '+state.round:'Исследование';$('turn').textContent='Ход '+a.genitive;$('party').replaceChildren();for(const p of state.party){const b=document.createElement('button');b.className='member '+(p.id===state.active?'active':'');b.disabled=p.hp<=0||busy;const portrait=document.createElement('div');portrait.className='portrait';portrait.append(art(p.kind*4));const n=document.createElement('b');n.textContent=p.name;const hp=document.createElement('small');hp.textContent=p.hp+'/'+p.max+' HP';const track=document.createElement('div');track.className='hp-track';const fill=document.createElement('i');fill.style.width=p.hp/p.max*100+'%';track.append(fill);b.append(portrait,n,hp,track);b.onclick=()=>{state.active=p.id;selected=null;path=[];save();render()};$('party').append(b)}for(const b of cells){const p={x:+b.dataset.x,y:+b.dataset.y},e=entity(p),o=prop(p);let klass='cell';if(selected&&same(selected,p))klass+=' selected';if(o&&['chest','altar','keeper'].includes(o.id))klass+=' interactive';if(e&&e.kind===3&&canAttack(a,e)&&state.combat)klass+=' attackable';if(!e&&!blocked(p)&&state.combat){const r=pathTo(a,p);if(r&&r.length<=a.move)klass+=' reachable'}b.className=klass;b.setAttribute('aria-label',e?e.name+', '+e.hp+' HP':o?o.name:blocked(p)?'Стена':'Клетка '+(p.x+1)+', '+(p.y+1));b.tabIndex=blocked(p)&&!o?-1:0}renderObjects();renderPieces();renderTarget();const action=primary();$('action').querySelector('b').textContent=action.label;$('action').disabled=busy||!action.enabled;$('action').onclick=action.fn||(()=>{});$('potion').disabled=busy||state.potions===0||a.hp>=a.max||a.hp<=0||(state.combat&&a.acted);$('end').disabled=busy||!state.combat;$('narrative').textContent=state.logs.at(-1);$('hint').textContent=state.complete?'Реликвия найдена. Приключение сохранено.':state.party.every(p=>p.hp<=0)?'Отряд пал. Новая игра доступна в меню.':path.length?'Маршрут: '+path.length+' клеток. Подтвердите движение.':state.combat?a.name+': '+a.move+' кл. · '+(a.acted?'действие потрачено':'1 действие'):'Подойдите к сундуку и алтарю.';$('resources').textContent='Ур. '+state.level+' · '+state.gold+' монет';terrain();window.renderViews?.()}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function travel(e,steps){for(const p of steps){face(e,p);e.x=p.x;e.y=p.y;renderPieces();await wait(matchMedia('(prefers-reduced-motion: reduce)').matches?0:170)}}
async function move(){const a=active(),r=path.slice();if(busy||!r.length||(state.combat&&r.length>a.move))return;busy=true;render();await travel(a,r);if(state.combat)a.move-=r.length;selected=null;path=[];busy=false;save();render()}
function damage(a,b,enemy=false){face(a,b);const n=roll(20,!enemy),bonus=enemy?2:a.attack,hit=n===20||(n!==1&&n+bonus>=12);const amount=hit?random(enemy?4:a.damage)+2+(n===20?random(enemy?4:a.damage):0):0;b.hp=Math.max(0,b.hp-amount);return a.name+': d20 '+n+' + '+bonus+' — '+(hit?(n===20?'критический удар, ':'')+amount+' урона.':'промах.')}
function finishBattle(){if(state.enemies.every(e=>e.hp<=0)&&state.combat){state.combat=false;state.xp+=60;tell('Стражи рассыпались. +60 опыта. Из-за алтаря выходит хранительница Эллен. Она знает, куда исчез колокол.')}}
function attack(e){const a=active();if(busy||!state.combat||!canAttack(a,e))return;tell(damage(a,e));a.acted=true;finishBattle();selected=e.hp>0?{x:e.x,y:e.y}:null;path=[];save();render()}
async function endTurn(){if(busy||!state.combat)return;busy=true;selected=null;path=[];render();for(const enemy of state.enemies.filter(e=>e.hp>0)){const targets=state.party.filter(p=>p.hp>0).sort((a,b)=>dist(enemy,a)-dist(enemy,b));if(!targets.length)break;const t=targets[0];if(dist(enemy,t)>1){const options=DIRS.map(([dx,dy])=>({x:t.x+dx,y:t.y+dy})).map(p=>pathTo(enemy,p)).filter(r=>r&&r.length).sort((a,b)=>a.length-b.length);if(options.length)await travel(enemy,options[0].slice(0,3))}if(dist(enemy,t)===1){tell(damage(enemy,t,true));render();await wait(250)}}if(state.party.every(p=>p.hp<=0)){state.combat=false;tell('Отряд пал. История этой попытки сохранена в хронике.')}else{state.round++;for(const p of state.party){p.move=p.kind===2?3:4;p.acted=false}if(active().hp<=0)state.active=state.party.find(p=>p.hp>0).id}busy=false;save();render()}
function potion(){const a=active();if($('potion').disabled)return;const heal=Math.min(10,a.max-a.hp);a.hp+=heal;state.potions--;if(state.combat)a.acted=true;tell(a.name+' выпивает зелье: +'+heal+' HP.');render()}
function interact(p){if(state.combat||dist(active(),p)!==1)return;if(p.id==='chest'){state.chest=true;state.gold+=15;state.potions++;tell('В сундуке — 15 монет, зелье и письмо: «Колокол увезли на север. Не верьте настоятелю». Зацепка сохранена.')}else{state.relic=true;state.complete=true;state.xp=Math.max(state.xp,100);state.gold+=30;tell('Реликвия найдена. +30 монет, +40 опыта. Серебряный язычок вернулся в часовню. Эллен ждёт у алтаря. Повышение уровня доступно во вкладке «Герой».')}render()}
function modal(title,content){$('modal-title').textContent=title;$('modal-body').innerHTML=content;$('modal').showModal()}
function journal(){modal('Хроника приключения','');for(const [i,text]of state.logs.entries()){const d=document.createElement('div');d.className='entry';const n=document.createElement('small');n.textContent='Событие '+(i+1);d.append(n,document.createTextNode(text));$('modal-body').append(d)}}
function help(){modal('Как играть','<ol><li>Выберите героя в верхней панели. У каждого своё перемещение и одно действие за раунд.</li><li>Нажмите клетку, затем «Идти». Подставки останавливаются строго в центре клетки.</li><li>Выберите врага, затем «Атака». Только четыре стороны. Для заклинания Миры цель должна находиться в той же строке или столбце, не дальше пяти клеток.</li><li>Герои и враги поворачиваются по последнему шагу и к цели перед ударом.</li><li>«Завершить ход» запускает противников и начинает новый раунд.</li><li>После боя откройте сундук и заберите реликвию, стоя на соседней клетке.</li></ol><p class="subtle">Броски использует криптографический генератор браузера. Эта глава — локальная игровая проба. ИИ-ведущий, Telegram и совместная игра пока не подключены.</p>')}
$('roll').onclick=()=>{const n=roll();tell('Свободный бросок d20: '+n+'.');render()};$('potion').onclick=potion;$('end').onclick=endTurn;$('journal').onclick=()=>window.openNarratorDialogue?window.openNarratorDialogue():journal();$('turn').onclick=help;$('close').onclick=()=>$('modal').close();$('menu').onclick=()=>{modal('Приключение','<p>Часовня без колокола · новая версия</p><p>Отряд из трёх героев. Прогресс сохраняется на этом устройстве.</p><div class="options"><button id="help">Как играть</button><button id="history">Хроника</button><button id="new">Новая игра</button></div>');$('help').onclick=()=>{$('modal').close();help()};$('history').onclick=()=>{$('modal').close();journal()};$('new').onclick=()=>{if(busy)return;state=fresh();selected=null;path=[];save();render();$('modal').close()}};
atlas.onload=cutAtlas;atlas.src='assets/cartoon-atlas.png';createCells();new ResizeObserver(terrain).observe($('board'));render();window.gameDebug={get state(){return state},get busy(){return busy},select,pathTo,line,canAttack,center:p=>({x:(p.x+.5)/W,y:(p.y+.5)/H}),render,art,active,save,tell,potion,journal,help,props,roll};window.initViews?.();
})();
